"""Build compact Unicode tables using the standard library's Unicode database."""
import sys
import unicodedata as ud


def generate(path):
    categories = {}
    for c in range(0x110000):
        cat = ud.category(chr(c))
        ranges = categories.setdefault(cat, [])
        if ranges and ranges[-1][1] == c - 1:
            ranges[-1][1] = c
        else:
            ranges.append([c, c])
    # Simple (one-codepoint) case folding, unlike full string casefolding.
    folds = {}
    for c in range(0x110000):
        ch = chr(c)
        f = ch.casefold()
        if len(f) != 1:
            f = ch.lower()
        if len(f) == 1 and f != ch:
            folds.setdefault(ord(f), set()).update([c, ord(f)])
    with open(path, 'w', encoding='utf-8') as out:
        out.write('# Generated from the Python Unicode database at build time.\n')
        out.write('CATEGORIES = ' + repr(categories) + '\n')
        out.write('FOLDS = ' + repr([sorted(x) for x in folds.values()]) + '\n')

if __name__ == '__main__':
    generate(sys.argv[1])
