"""Unicode sets and their UTF-8 regular-language representation.

Expressions operate on bytes. Unicode atoms are compiled to sequences of bytes,
so invalid UTF-8 is preserved and zero-width matching remains byte oriented.
"""
import functools
import unicodedata
try:
    from unicode_tables import CATEGORIES, FOLDS
except ImportError:
    CATEGORIES = {}
    FOLDS = []

MAX = 0x10ffff
SCALARS = [(0, 0xd7ff), (0xe000, MAX)]


def union(*sets):
    values = sorted(r for s in sets for r in s)
    out = []
    for lo, hi in values:
        if lo > hi:
            continue
        if out and lo <= out[-1][1] + 1:
            out[-1] = (out[-1][0], max(hi, out[-1][1]))
        else:
            out.append((lo, hi))
    return out


def intersect(a, b):
    a, b = union(a), union(b)
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        lo, hi = max(a[i][0], b[j][0]), min(a[i][1], b[j][1])
        if lo <= hi:
            out.append((lo, hi))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return out


def subtract(a, b):
    a, b = union(a), union(b)
    out = []
    j = 0
    for lo, hi in a:
        while j < len(b) and b[j][1] < lo:
            j += 1
        k = j
        while k < len(b) and b[k][0] <= hi:
            if b[k][0] > lo:
                out.append((lo, b[k][0] - 1))
            lo = max(lo, b[k][1] + 1)
            if lo > hi:
                break
            k += 1
        if lo <= hi:
            out.append((lo, hi))
    return out


def negate(a, unicode=True):
    return subtract(SCALARS if unicode else [(0, 255)], a)


def contains(s, c):
    # Ranges are ordered; binary search avoids scanning large Unicode classes.
    l, r = 0, len(s)
    while l < r:
        m = (l + r) // 2
        if s[m][1] < c:
            l = m + 1
        else:
            r = m
    return l < len(s) and s[l][0] <= c <= s[l][1]


def fold(s, unicode=True):
    s = union(s)
    extra = []
    if unicode:
        for group in FOLDS:
            if any(contains(s, c) for c in group):
                extra.extend((c, c) for c in group)
    else:
        for c in range(65, 91):
            if contains(s, c) or contains(s, c + 32):
                extra.extend([(c, c), (c + 32, c + 32)])
    return union(s, extra)


SPACE = [(9, 13), (32, 32), (133, 133), (160, 160), (0x1680, 0x1680),
         (0x2000, 0x200a), (0x2028, 0x2029), (0x202f, 0x202f),
         (0x205f, 0x205f), (0x3000, 0x3000)]
ASCII = {
    'alnum': [(48, 57), (65, 90), (97, 122)],
    'alpha': [(65, 90), (97, 122)], 'ascii': [(0, 127)],
    'blank': [(9, 9), (32, 32)], 'cntrl': [(0, 31), (127, 127)],
    'digit': [(48, 57)], 'graph': [(33, 126)], 'lower': [(97, 122)],
    'print': [(32, 126)], 'punct': [(33, 47), (58, 64), (91, 96), (123, 126)],
    'space': [(9, 13), (32, 32)], 'upper': [(65, 90)],
    'word': [(48, 57), (65, 90), (95, 95), (97, 122)],
    'xdigit': [(48, 57), (65, 70), (97, 102)]
}

CATEGORY_NAMES = {
    'letter':'L', 'casedletter':'LC', 'uppercaseletter':'Lu', 'lowercaseletter':'Ll',
    'titlecaseletter':'Lt', 'modifierletter':'Lm', 'otherletter':'Lo', 'mark':'M',
    'nonspacingmark':'Mn', 'spacingmark':'Mc', 'spacingcombiningmark':'Mc',
    'enclosingmark':'Me', 'number':'N', 'decimalnumber':'Nd', 'decimaldigitnumber':'Nd',
    'letternumber':'Nl', 'othernumber':'No', 'punctuation':'P', 'connectorpunctuation':'Pc',
    'dashpunctuation':'Pd', 'openpunctuation':'Ps', 'closepunctuation':'Pe',
    'initialpunctuation':'Pi', 'finalpunctuation':'Pf', 'otherpunctuation':'Po',
    'symbol':'S', 'mathsymbol':'Sm', 'currencysymbol':'Sc', 'modifiersymbol':'Sk',
    'othersymbol':'So', 'separator':'Z', 'spaceseparator':'Zs', 'lineseparator':'Zl',
    'paragraphseparator':'Zp', 'other':'C', 'control':'Cc', 'format':'Cf',
    'surrogate':'Cs', 'privateuse':'Co', 'unassigned':'Cn'
}


def normalize(s):
    return ''.join(c.lower() for c in s if c not in ' _-\t\r\n')


def category(s):
    s = normalize(s)
    s = CATEGORY_NAMES.get(s, s)
    return union(*(ranges for key, ranges in CATEGORIES.items()
                   if key.lower() == s.lower() or len(s) == 1 and key[0].lower() == s.lower()
                   or s == 'LC' and key in ('Lu', 'Ll', 'Lt')))


@functools.lru_cache(maxsize=128)
def prop(name):
    n = normalize(name)
    invert = False
    if '!=' in n:
        k, n = n.split('!=', 1)
        invert = True
    elif '=' in n or ':' in n:
        k, n = n.replace(':', '=').split('=', 1)
    else:
        k = ''
    if k in ('gc', 'generalcategory', ''):
        cat = category(n)
        if cat or n in ('cs', 'surrogate'):
            out = intersect(cat, SCALARS)
            return negate(out) if invert else out
    out = None
    if not k:
        if n in ('any',):
            out = SCALARS
        elif n == 'ascii':
            out = [(0,127)]
        elif n in ('whitespace', 'space', 'wspace'):
            out = SPACE
        elif n in ('word',):
            out = word()
        elif n in ('assigned',):
            out = negate(category('Cn'))
        elif n in ('joincontrol',):
            out = [(0x200c,0x200d)]
        elif n in ('hexdigit','xdigit'):
            out = union(ASCII['xdigit'], [(0xff10,0xff19),(0xff21,0xff26),(0xff41,0xff46)])
        elif n == 'asciihexdigit':
            out = ASCII['xdigit']
        elif n in ('alphabetic','alpha'):
            out = _scan(lambda c: c.isalpha() or unicodedata.category(c) == 'Nl')
        elif n in ('lowercase','lower'):
            out = _scan(str.islower)
        elif n in ('uppercase','upper'):
            out = _scan(str.isupper)
        elif n == 'cased':
            out = _scan(lambda c: c.islower() or c.isupper() or unicodedata.category(c) == 'Lt')
    if out is None:
        # The optional OS Unicode property engine supplies script tables.
        # It is a general-purpose regex library, not a search/replace program.
        out = _property_from_system(name)
    if out is None:
        raise KeyError(name)
    return negate(out) if invert else out


@functools.lru_cache(maxsize=1)
def word():
    return union(category('L'), category('M'), category('Nd'), category('Nl'),
                 category('Pc'), [(0x200c,0x200d)])


def perl(c, unicode=True):
    base = {'d':category('Nd') if unicode else ASCII['digit'],
            's':SPACE if unicode else ASCII['space'],
            'w':word() if unicode else ASCII['word']}[c.lower()]
    return negate(base, unicode) if c.isupper() else base


def _scan(pred):
    out = []
    start = None
    for c in range(MAX + 1):
        ok = not 0xd800 <= c <= 0xdfff and pred(chr(c))
        if ok and start is None:
            start = c
        elif not ok and start is not None:
            out.append((start,c-1));start=None
    if start is not None:
        out.append((start,MAX))
    return out


def _property_from_system(name):
    try:
        import ctypes as ct
        lib = ct.CDLL('libpcre2-32.so.0')
        lib.pcre2_compile_32.restype = ct.c_void_p
        lib.pcre2_compile_32.argtypes = [ct.c_void_p,ct.c_size_t,ct.c_uint32,ct.c_void_p,ct.c_void_p,ct.c_void_p]
        lib.pcre2_match_data_create_from_pattern_32.restype = ct.c_void_p
        lib.pcre2_match_data_create_from_pattern_32.argtypes = [ct.c_void_p,ct.c_void_p]
        lib.pcre2_match_32.argtypes = [ct.c_void_p,ct.c_void_p,ct.c_size_t,ct.c_size_t,ct.c_uint32,ct.c_void_p,ct.c_void_p]
        lib.pcre2_get_ovector_pointer_32.restype = ct.POINTER(ct.c_size_t)
        lib.pcre2_get_ovector_pointer_32.argtypes = [ct.c_void_p]
        lib.pcre2_code_free_32.argtypes = [ct.c_void_p]
        lib.pcre2_match_data_free_32.argtypes = [ct.c_void_p]
        name = name.replace('Script_Extensions=', 'scx=').replace('Script=', 'sc=')
        pat = '\\p{' + name + '}+'
        buf = (ct.c_uint32 * len(pat))(*(ord(c) for c in pat))
        err, off = ct.c_int(), ct.c_size_t()
        code = lib.pcre2_compile_32(buf,len(pat),0,ct.byref(err),ct.byref(off),None)
        if not code:
            return None
        md = lib.pcre2_match_data_create_from_pattern_32(code,None)
        subjects = (ct.c_uint32 * (MAX+1))(*range(MAX+1))
        pos, out = 0, []
        while pos <= MAX:
            rc = lib.pcre2_match_32(code,subjects,MAX+1,pos,0,md,None)
            if rc < 0:
                break
            ov = lib.pcre2_get_ovector_pointer_32(md)
            out.append((ov[0],ov[1]-1));pos=ov[1]
        lib.pcre2_match_data_free_32(md);lib.pcre2_code_free_32(code)
        return intersect(out,SCALARS)
    except (OSError, AttributeError):
        return None


def bclass(ranges):
    if not ranges:
        return b'(?!)'
    def b(c):
        return ('\\x%02x' % c).encode()
    if len(ranges) == 1 and ranges[0][0] == ranges[0][1]:
        return b(ranges[0][0])
    return b'[' + b''.join(b(lo) if lo == hi else b(lo)+b'-'+b(hi) for lo,hi in ranges) + b']'


def _rects(lo,hi):
    """Partition one lexicographic UTF-8 interval into Cartesian byte ranges."""
    if not lo:
        return [()]
    if lo[0] == hi[0]:
        return [((lo[0],lo[0]),)+r for r in _rects(lo[1:],hi[1:])]
    if len(lo) == 1:
        return [((lo[0],hi[0]),)]
    tail_lo = [0x80] * (len(lo)-1)
    tail_hi = [0xbf] * (len(lo)-1)
    result = [((lo[0],lo[0]),)+r for r in _rects(lo[1:],tail_hi)]
    if lo[0]+1 <= hi[0]-1:
        result.append(((lo[0]+1,hi[0]-1),)+tuple((0x80,0xbf) for _ in tail_lo))
    result.extend(((hi[0],hi[0]),)+r for r in _rects(tail_lo,hi[1:]))
    return result


@functools.lru_cache(maxsize=256)
def utf8_parts(ranges):
    by_len = {1:[],2:[],3:[],4:[]}
    for low,high in ranges:
        for lo,hi in intersect([(low,high)], [(0,0x7f),(0x80,0x7ff),(0x800,0xd7ff),(0xe000,0xffff),(0x10000,MAX)]):
            # intersect merges adjacent intervals; split explicitly by length.
            for a,b in [(0,127),(128,0x7ff),(0x800,0xd7ff),(0xe000,0xffff),(0x10000,MAX)]:
                l,h=max(a,lo),min(b,hi)
                if l>h: continue
                lb,hb=list(chr(l).encode()),list(chr(h).encode())
                by_len[len(lb)].extend(_rects(lb,hb))
    parts = {}
    for length,rects in by_len.items():
        if not rects: continue
        # Fold rectangles with a common suffix into a single byte class.
        def trie(items, depth):
            if depth == length:
                return b''
            groups = {}
            for r in items:
                groups.setdefault(r[depth],[]).append(r)
            suffixes = {}
            for interval,group in groups.items():
                suffix = trie(group,depth+1)
                suffixes.setdefault(suffix,[]).append(interval)
            alts = [bclass(union(v))+k for k,v in suffixes.items()]
            return alts[0] if len(alts)==1 else b'(?:'+b'|'.join(alts)+b')'
        parts[length]=trie(rects,0)
    return parts


def compile_set(ranges, unicode=True):
    ranges = union(ranges)
    if not unicode:
        return bclass(ranges)
    parts = utf8_parts(tuple(ranges))
    alts = list(parts.values())
    if not alts:
        return b'(?!)'
    return alts[0] if len(alts)==1 else b'(?:'+b'|'.join(alts)+b')'
EOF"}

